/* BlastTier: clean fixed JS. Original CSS/design is untouched. */
const LOGOS={"overall": "data:image/png;base64,", "ltms": "data:image/png;base64,", "vanilla": "data:image/png;base64,", "uhc": "data:image/png;base64,", "pot": "data:image/png;base64,", "nethop": "data:image/png;base64,", "smp": "data:image/png;base64,", "sword": "data:image/png;base64,", "axe": "data:image/png;base64,", "mace": "data:image/png;base64,"};
const DEFAULT_KITS=[["LTMs","ltms"],["Vanilla","vanilla"],["UHC","uhc"],["Pot","pot"],["NethOP","nethop"],["SMP","smp"],["Sword","sword"],["Axe","axe"],["Mace","mace"]];
let players=JSON.parse(localStorage.getItem("bt_players")||"[]");
let kits=JSON.parse(localStorage.getItem("bt_kits")||"null");
let tiers=JSON.parse(localStorage.getItem("bt_tiers")||"[]");
let chats=JSON.parse(localStorage.getItem("bt_chats")||"[]");
let selectedIcon="sword";
if(!Array.isArray(kits))kits=DEFAULT_KITS.map(x=>({name:x[0],icon:x[1],builtin:true}));
function save(){localStorage.setItem("bt_players",JSON.stringify(players));localStorage.setItem("bt_kits",JSON.stringify(kits));localStorage.setItem("bt_tiers",JSON.stringify(tiers));localStorage.setItem("bt_chats",JSON.stringify(chats))}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function logo(k){return `<span class="embedded-logo"><img src="${LOGOS[k]||LOGOS.sword}" alt=""></span>`}
function buildTabs(){
 const b=document.getElementById("tabs");if(!b)return;
 b.innerHTML='<button class="tab active" data-kit="Overall"><span class="ico">🏆</span><span>Overall</span></button>'+
 kits.map(k=>`<button class="tab" data-kit="${esc(k.name)}"><span class="ico">${logo(k.icon)}</span><span>${esc(k.name)}</span></button>`).join("");
 b.querySelectorAll(".tab").forEach(x=>x.addEventListener("click",()=>{b.querySelectorAll(".tab").forEach(y=>y.classList.remove("active"));x.classList.add("active")}));
}
function fillSelects(){
 const p=document.getElementById("ptier"),k=document.getElementById("tkit");
 if(p)p.innerHTML='<option value="">No tier</option>'+tiers.map(t=>`<option value="${esc(t.name)}">${esc(t.name)}</option>`).join("");
 if(k)k.innerHTML=kits.length?kits.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join(""):'<option value="">No kit</option>';
}
function renderPlayers(){
 const q=(document.getElementById("search")?.value||"").toLowerCase(),rows=document.getElementById("rows");if(!rows)return;
 const list=players.filter(p=>String(p.name||"").toLowerCase().includes(q)).sort((a,b)=>(Number(b.points)||0)-(Number(a.points)||0));
 if(!list.length){rows.innerHTML='<div class="empty"><div class="emptyIcon">🏆</div><h2>No players yet!</h2><p>Add players to start building the BlastTier rankings.</p></div>';return}
 rows.innerHTML=list.map((p,i)=>`<div class="row"><div class="rank">${i+1}.</div><div class="player"><div class="skin">${p.skin?`<img src="${p.skin}" alt="">`:esc(String(p.name||"").slice(0,2).toUpperCase())}</div><div><div class="pname">${esc(p.name)}</div><div class="sub"><b>◆</b> ${esc(p.rank)} <span>(${esc(p.points)} points)</span></div></div></div><div><span class="region">${esc(p.region)}</span></div><div class="tierbox">${(p.tiers||[]).length?(p.tiers||[]).map(t=>{let z=tiers.find(a=>a.name===t);return `<div class="tierbadge"><div class="kitcircle">${logo(z?.icon||"sword")}</div><div class="tiername">${esc(t)}</div></div>`}).join(""):'<span style="color:#667d93">No tiers</span>'}<button type="button" class="delete-player" data-player="${esc(p.name)}">Delete</button></div></div>`).join("");
 rows.querySelectorAll(".delete-player").forEach(b=>b.addEventListener("click",()=>deletePlayer(b.dataset.player)));
}
function deletePlayer(name){
 const p=players.find(x=>x.name===name);
 if(!p)return;
 if(!confirm(`Delete player "${name}"?`))return;
 players=players.filter(x=>x.name!==name);
 save();
 renderPlayers();
}
function renderKitGrid(){
 const g=document.getElementById("kitGrid");if(!g)return;
 g.innerHTML=kits.map(k=>`<div class="kitcard"><div class="kitbig">${logo(k.icon)}</div>${esc(k.name)}</div>`).join("");
}
function buildIconPicker(){
 const b=document.getElementById("iconPicker");if(!b)return;
 b.innerHTML=Object.keys(LOGOS).map(k=>`<button type="button" class="iconPick ${selectedIcon===k?"selected":""}" data-icon="${k}">${logo(k)}<br><small>${k}</small></button>`).join("");
 b.querySelectorAll("[data-icon]").forEach(x=>x.addEventListener("click",()=>{selectedIcon=x.dataset.icon;buildIconPicker()}));
}
function openModal(t){document.getElementById(t+"Modal")?.classList.add("show");fillSelects();if(t==="kit")buildIconPicker()}
function closeModals(){document.querySelectorAll(".modal").forEach(x=>x.classList.remove("show"))}
function addKit(){
 const i=document.getElementById("kname"),n=(i?.value||"").trim();if(!n)return alert("Enter a kit name.");
 if(kits.some(k=>k.name.toLowerCase()===n.toLowerCase()))return alert("Kit already exists.");
 kits.push({name:n,icon:selectedIcon});save();i.value="";selectedIcon="sword";closeModals();buildTabs();renderKitGrid();fillSelects();
}
function addTier(){
 const n=(document.getElementById("tname")?.value||"").trim(),kn=document.getElementById("tkit")?.value;if(!n)return alert("Enter a tier name.");if(!kn)return alert("Add a kit first.");
 const k=kits.find(x=>x.name===kn);if(tiers.some(t=>t.name.toLowerCase()===n.toLowerCase()&&t.kit===kn))return alert("That tier already exists.");
 tiers.push({name:n,kit:kn,icon:k?.icon||"sword"});save();document.getElementById("tname").value="";closeModals();fillSelects();
}
function addPlayer(){
 const n=(document.getElementById("pn")?.value||"").trim();if(!n)return alert("Enter a player name.");
 if(players.some(p=>p.name.toLowerCase()===n.toLowerCase()))return alert("Player already exists.");
 const p={name:n,rank:document.getElementById("prank").value,points:Number(document.getElementById("pp").value)||0,region:document.getElementById("preg").value,tiers:document.getElementById("ptier").value?[document.getElementById("ptier").value]:[],skin:""};
 const f=document.getElementById("pskin")?.files?.[0],done=()=>{players.push(p);save();document.getElementById("pn").value="";document.getElementById("pskin").value="";closeModals();renderPlayers()};
 if(f){const r=new FileReader();r.onload=e=>{p.skin=e.target.result;done()};r.onerror=()=>alert("Could not read skin.");r.readAsDataURL(f)}else done();
}
function renderChat(){const b=document.getElementById("messages");if(!b)return;b.innerHTML=chats.length?chats.map(m=>`<div class="msg"><b style="color:#42a3ff">${esc(m.name)}</b> <small style="color:#68819a">${esc(m.time)}</small><div style="margin-top:5px">${esc(m.text)}</div></div>`).join(""):'<div style="text-align:center;color:#617a91;padding-top:180px">No messages yet.</div>';b.scrollTop=b.scrollHeight}
function sendChat(){const i=document.getElementById("chatInput"),t=(i?.value||"").trim();if(!t)return;chats.push({name:"You",text:t,time:new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})});i.value="";save();renderChat()}
function page(n,b){document.querySelectorAll(".panel").forEach(x=>x.classList.remove("show"));document.getElementById(n)?.classList.add("show");document.querySelectorAll(".nav button").forEach(x=>x.classList.remove("active"));b?.classList.add("active");if(n==="rankings"){buildTabs();renderPlayers();renderKitGrid();fillSelects()}if(n==="chat")renderChat()}
window.openModal=openModal;window.closeModals=closeModals;window.addKit=addKit;window.addTier=addTier;window.addPlayer=addPlayer;window.deletePlayer=deletePlayer;window.sendChat=sendChat;
document.addEventListener("DOMContentLoaded",()=>{
 document.querySelectorAll(".nav button").forEach(b=>b.addEventListener("click",()=>page(b.dataset.page,b)));
 document.querySelectorAll(".modal").forEach(m=>m.addEventListener("click",e=>{if(e.target===m)closeModals()}));
 document.getElementById("search")?.addEventListener("input",renderPlayers);
 document.getElementById("chatInput")?.addEventListener("keydown",e=>{if(e.key==="Enter")sendChat()});
 buildTabs();fillSelects();renderPlayers();renderKitGrid();renderChat();
 const home=document.getElementById("home");
 if(home)home.classList.add("show");
});
